css:
button {
  --green: #f25012;
  font-size: 15px;
  padding: 0.7em 2.7em;
  letter-spacing: 0.06em;
  position: relative;
  font-family: inherit;
  border-radius: 0.6em;
  overflow: hidden;
  transition: all 0.3s;
  line-height: 1.4em;
  border: 2px solid var(--green);
  background: linear-gradient(
    to right,
    rgba(243, 78, 22, 0.1) 1%,
    transparent 40%,
    transparent 60%,
    rgba(243, 78, 22, 0.1) 100%
  );
  color: var(--green);
  box-shadow:
    inset 0 0 10px rgba(243, 78, 22, 0.4),
    0 0 9px 3px rgba(243, 78, 22, 0.1);
}

button:hover {
  color: #f25012;
  box-shadow:
    inset 0 0 10px rgba(243, 78, 22, 0.6),
    0 0 9px 3px rgba(243, 78, 22, 0.2);
}

button:before {
  content: "";
  position: absolute;
  left: -4em;
  width: 4em;
  height: 100%;
  top: 0;
  transition: transform 0.4s ease-in-out;
  background: linear-gradient(
    to right,
    transparent 1%,
    rgba(243, 78, 22, 0.1) 40%,
    rgba(243, 78, 22, 0.1) 60%,
    transparent 100%
  );
}

button:hover:before {
  transform: translateX(15em);
}
